function solution(nums, target) {
  let left = 0;
  let right = nums.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const num = nums[mid];

    if (num === target) return mid;
    num < target ? (left = mid + 1) : (right = mid - 1);
  }

  return left;
}

